// #73717d (a267e2d2a28f85ea9d73717d) — истёкшее приглашение: «פג תוקף», без метки сбоя отправки и без копирования
// ссылки, есть повторная отправка — в /settings/users (business) и в карточке бизнеса у Super Admin. Кейс BIZ-INV-008.
// Данные: настоящие истёкшие приглашения testim «QA-7b fail 1013» (было send_failed) и «QA-7b ok2 1013» (истекли
// 20.10.2026). Имена можно задать QA_EXPIRED_INVITES="имя1,имя2". Только чтение: «שליחה חוזרת / שליחה מחדש» НЕ
// нажимаются (иначе приглашение перестанет быть истёкшим) → @prod-safe.
import { test, expect } from '../../fixtures';
import { openWithApi } from '../support/api';

const HASH = '#73717d · #a267e2d2a28f85ea9d73717d';
const EXPIRED = (process.env.QA_EXPIRED_INVITES || 'QA-7b fail 1013,QA-7b ok2 1013').split(',').map((s) => s.trim()).filter(Boolean);
const BUSINESS = process.env.QA_TESTIM_BUSINESS || 'testim';

test.describe(`Приглашения — истёкшее приглашение (${HASH})`, () => {
  test(`/settings/users: истёкшее приглашение — «פג תוקף», без «שליחת המייל נכשלה», в меню только «שליחה חוזרת» @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const page = await asUser('business');
    await page.goto('/settings/users');
    await expect(page.getByRole('heading', { level: 1, name: 'משתמשים והרשאות' })).toBeVisible();

    for (const name of EXPIRED) {
      const row = page.getByTestId('user-row').filter({ hasText: name });
      await expect(row, `нет строки приглашения «${name}» в /settings/users`).toHaveCount(1);
      await expect(row, `«${name}» уже не истёкшее (переотправлено?) — нужен другой истёкший пример в QA_EXPIRED_INVITES`).toHaveAttribute('data-status', 'expired');

      // Источник: AC — «הזמנה שפג תוקפה מוצגת כ"פג תוקף"», метка сбоя — только у ממתינה בתוקף.
      const status = row.locator('td[data-label="סטטוס"]');
      await expect(status).toContainText('פג תוקף');
      await expect(row).not.toContainText('שליחת המייל נכשלה');
      await expect(row).not.toContainText('מייל ההזמנה לא נמסר');
      await expect(row).not.toContainText('בתוקף עד');
      await expect(row.getByTestId('delivery-failure')).toHaveCount(0);

      // Источник: AC — «עם שליחה מחדש ובלי העתקת קישור». Меню только открывается, пункты не нажимаются.
      const menuName = `פעולות עבור ההזמנה של ${name}`;
      await row.getByRole('button', { name: menuName }).click();
      const menu = page.getByRole('menu', { name: menuName });
      await expect(menu).toBeVisible();
      await expect(menu.getByRole('menuitem')).toHaveText(['שליחה חוזרת']);
      await expect(menu.getByRole('menuitem', { name: 'העתקת קישור' })).toHaveCount(0);
      await page.keyboard.press('Escape');
      await expect(menu).toBeHidden();
    }
  });

  test(`карточка бизнеса у Super Admin: те же истёкшие приглашения — «פג תוקף», без метки сбоя, единственная кнопка «שליחה מחדש» @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const page = await asUser('admin');
    const api = await openWithApi(page, '/admin/businesses');
    const res = await api.rpc('admin_list_businesses');
    expect(res.status(), `admin_list_businesses: ${await res.text()}`).toBe(200);
    const found = ((await res.json()) as { id: string; name: string }[]).filter((b) => b.name === BUSINESS);
    expect(found, `бизнес «${BUSINESS}» (QA_TESTIM_BUSINESS)`).toHaveLength(1);

    await page.goto(`/admin/businesses/${found[0].id}`);
    await expect(page.getByRole('heading', { level: 1, name: BUSINESS })).toBeVisible();
    const invitations = page.getByRole('region', { name: 'הזמנות' });

    for (const name of EXPIRED) {
      const row = invitations.getByRole('row').filter({ hasText: name });
      await expect(row, `нет строки «${name}» в блоке «הזמנות»`).toHaveCount(1);
      // Источник: «מצב נדרש: אותו כלל תוויות בשני המסכים».
      const status = row.getByRole('cell').nth(2);
      await expect(status).toContainText('פג תוקף');
      await expect(status).not.toContainText('שליחת המייל נכשלה');
      await expect(status).not.toContainText('בתוקף עד');
      await expect(row.getByRole('button')).toHaveCount(1);
      await expect(row.getByRole('button', { name: 'שליחה מחדש' })).toBeVisible();
    }
  });
});
